-- challenge chal_quiz_csf_111 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_csf_111', (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-csf-1-1' AND is_deleted = false LIMIT 1), 'value-reference-numbers-quiz', 'Predict it: copies, integer division and rounding', 'Follow a struct and a class through an assignment, then decide which number snippets behave the way their authors expected.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_111'), 'Seat is a struct and Desk is a class; both have one public int field, Row. What does this print?

var a = new Seat { Row = 1 };
var b = a;
b.Row = 2;

var c = new Desk { Row = 1 };
var d = c;
d.Row = 2;

Console.WriteLine($"{a.Row} {c.Row}");', 'single_choice'::question_type, 'Seat is a struct, a value type: var b = a copies every field, so b is a separate Seat and b.Row = 2 leaves a.Row at 1. Desk is a class, a reference type: var d = c copies only the reference, so c and d are two names for one Desk object, and d.Row = 2 is visible through c. The output is "1 2". "1 1" is what you would get if Desk were a struct too, "2 2" if Seat were a class. "2 1" cannot happen with any combination.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('1 1', false),
        ('1 2', true),
        ('2 2', false),
        ('2 1', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_111'), 'Which of these statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'attended / sessions is int / int, so 9 / 12 is 0 and 0 * 100 is 0: write 100.0 * attended / sessions. Math.Round(2.5m) uses MidpointRounding.ToEven by default and returns 2 (the nearest even number); pass MidpointRounding.AwayFromZero to get 3. var fee = 1_800_000 makes fee an int, and fee * 1.1 is a double, so the assignment is the compile error CS0266 "Cannot implicitly convert type ''double'' to ''int''". string, arrays and classes are reference types; int, decimal, bool and structs are value types. decimal stores 0.1, 0.2 and 0.3 exactly, so 0.1m + 0.2m == 0.3m is true (with double it is false: 0.30000000000000004). int[] b = a copies the reference to the one array, so b[0] = 9 also changes a[0].', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('int sessions = 12, attended = 9; Console.WriteLine(attended / sessions * 100); prints 0', true),
        ('Math.Round(2.5m) returns 3', false),
        ('var fee = 1_800_000; fee = fee * 1.1; compiles, and fee becomes 1980000', false),
        ('string, arrays and classes are reference types; int, decimal, bool and structs are value types', true),
        ('0.1m + 0.2m == 0.3m is true', true),
        ('int[] a = [1, 2]; int[] b = a; b[0] = 9; leaves a[0] equal to 1', false)
    ) AS o(option_text, is_correct);

