-- challenge chal_quiz_csf_121 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_csf_121', (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-csf-1-2' AND is_deleted = false LIMIT 1), 'nullable-operators-quiz', 'Predict it: ?., ?? and what the compiler checks', 'Follow a guardian without a phone through ?. and ??, then decide which statements about nullable reference types are true.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_121'), 'Guardian has two properties, string? Phone and string? Email. What does this print?

Guardian? g = new Guardian { Email = "ha@example.vn" };

string contact = g?.Phone ?? g?.Email ?? "none";
int? length = g?.Phone?.Length;

Console.WriteLine($"{contact} {length ?? -1}");', 'single_choice'::question_type, 'g is not null, so g?.Phone reads the property: it is null, because the initializer only set Email. ?? moves on to g?.Email, which is "ha@example.vn", so contact is the email and "none" is never used. In g?.Phone?.Length the second ?. sees a null Phone and the whole expression is null - an int? without a value, not 0. length ?? -1 then gives -1. Nothing throws: every access that could hit null goes through ?. (a plain g.Phone.Length would throw a NullReferenceException).', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_121') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('ha@example.vn -1', true),
        ('none -1', false),
        ('ha@example.vn 0', false),
        ('It throws a NullReferenceException', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_121'), 'A project has <Nullable>enable</Nullable> and no WarningsAsErrors. Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'The ! operator only tells the compiler "trust me": phone!.Length compiles without a warning, and if phone is null it still throws a NullReferenceException at run time. After if (string.IsNullOrWhiteSpace(phone)) return; the compiler knows phone is not null, because the method is annotated [NotNullWhen(false)]. GetValueOrDefault(id) on a Dictionary<string, string> returns default(string), which is null, when the key is missing; its return type is string?. string? is an annotation for the compiler: nothing is checked at run time, and no ArgumentNullException appears by itself (ArgumentNullException.ThrowIfNull does that). string name = null; is a warning (CS8600), not an error, until you add <WarningsAsErrors>nullable</WarningsAsErrors>. x ??= y assigns y only when x is null.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_121') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('string? phone = null; int n = phone!.Length; compiles without a warning and throws a NullReferenceException at run time', true),
        ('After if (string.IsNullOrWhiteSpace(phone)) return; the compiler treats phone as not null', true),
        ('phones.GetValueOrDefault(id) on a Dictionary<string, string> can return null', true),
        ('Declaring a property as string? Phone makes the runtime throw an ArgumentNullException when it is read while null', false),
        ('string name = null; is a compile error', false),
        ('x ??= y assigns y to x every time it runs', false)
    ) AS o(option_text, is_correct);

-- challenge chal_fix_csf_122 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_csf_122', (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-csf-1-2' AND is_deleted = false LIMIT 1), 'fix-class-reminders-null', 'Fix the Sunday reminder job that crashes on missing contacts', 'Every Sunday at 20:00 Sen Academy sends each guardian a reminder for Monday''s class: by SMS when there is a phone number, by email otherwise, and the student is skipped when there is neither. Guardians may now register with an email only, older students may have no guardian on file, and a phone number changed through the Zalo form wins over the signup form. The job crashes with a NullReferenceException and nobody gets a reminder. Fix BuildReminder so that missing guardians, missing or blank phones and missing or blank emails are handled, and the updated phone is used whenever there is one. The test runner reads the students and the phone updates, then prints one reminder per student and the totals.', 'open', 'easy'::difficulty_question, 'fix_bug', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
