-- challenge chal_quiz_csf_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_csf_131', (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-csf-1-3' AND is_deleted = false LIMIT 1), 'culture-parsing-quiz', 'Predict it: one string, two cultures', 'Parse and format a score on a server with Vietnamese settings, then decide which string operations do what their authors expected.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_131'), 'The import worker runs with Vietnamese settings. What does this print?

CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo("vi-VN");

decimal score = decimal.Parse("8.5");
Console.WriteLine($"{score} {score / 10:F2}");', 'single_choice'::question_type, 'decimal.Parse without a culture uses the current culture. In vi-VN the dot is the thousands separator and the comma is the decimal separator, and the default NumberStyles accepts thousands separators anywhere, so "8.5" is read as 85 - no exception. score / 10 is 8.5, and both interpolation holes format with the current culture too: 85 prints as "85" and 8.5 with F2 as "8,50". The output is "85 8,50". "8.5 0.85" is what an invariant server prints. "8,5 0,85" would need the parse to be right and only the formatting to be Vietnamese. There is no FormatException: a misplaced group separator is accepted.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('8.5 0.85', false),
        ('8,5 0,85', false),
        ('85 8,50', true),
        ('It throws a FormatException', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_131'), 'Which of these statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'In the invariant culture the comma is the thousands separator, so decimal.Parse("8,5", CultureInfo.InvariantCulture) returns 85: choosing the right culture is not enough when the input itself is wrong. NumberStyles.Float does not include AllowThousands, so TryParse with it rejects "8,5" and returns false - the row can be reported instead of imported as 85. Ordinal comparison with OrdinalIgnoreCase compares the characters ignoring case, so "toan9-a" equals "TOAN9-A". F1 is a fixed-point format, but its decimal separator still comes from the culture: on a vi-VN thread $"{8.5m:F1}" is "8,5". Strings are immutable: classCode.ToUpperInvariant() returns a new string, and without classCode = ... the result is lost. "Nguyễn".Length counts UTF-16 code units: 6 when ễ is one precomposed character, 8 when the same name arrives decomposed (e + two combining marks), for example pasted from some macOS apps.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('decimal.Parse("8,5", CultureInfo.InvariantCulture) returns 85', true),
        ('decimal.TryParse("8,5", NumberStyles.Float, CultureInfo.InvariantCulture, out var s) returns false', true),
        ('"toan9-a".Equals("TOAN9-A", StringComparison.OrdinalIgnoreCase) is true', true),
        ('$"{score:F1}" always prints a dot, because F1 is a fixed-point format', false),
        ('classCode.ToUpperInvariant(); changes classCode to upper case', false),
        ('"Nguyễn".Length is always 6', false)
    ) AS o(option_text, is_correct);

-- challenge chal_fix_csf_132 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_csf_132', (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-csf-1-3' AND is_deleted = false LIMIT 1), 'fix-score-import-culture', 'Fix the score import on the Vietnamese server', 'Teachers upload term scores with a dot for decimals (8.5). Since the import worker moved to a container image with Vietnamese settings, scores like 8.5 are read as 85 and rejected, and the CSV export writes 8,3, which adds a column for the reporting tools. The SMS to parents, on the other hand, must keep the Vietnamese decimal comma. Fix TryParseScore, CsvRow and SmsText so that parsing and the CSV export use the invariant culture, the SMS uses vi-VN, and none of them depends on the server''s current culture. The test runner sets the current culture to vi-VN, reads one student per line and prints the CSV row and SMS text for every valid line, an error for every invalid one, and the totals.', 'open', 'medium'::difficulty_question, 'fix_bug', 20, true, false)
