       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_csf_132'), 'Out of range, malformed, missing and padded scores', '"HS-1024,Nguyễn Gia Bảo,11,8\nHS-1025,Trần Khánh Linh,8,-1\nHS-1026,Lê Hoàng Nam,8.5.1\nHS-1027,Đỗ Mai Anh,7,1.000\nHS-1028,Vũ Đức Huy\nHS-1029,Hoàng Thu Trang,  9.5 ,8.25\n"', '"error line 1: bad score ''11''\nerror line 2: bad score ''-1''\nerror line 3: bad score ''8.5.1''\ncsv HS-1027,Đỗ Mai Anh,4.0\nsms Đỗ Mai Anh - điểm trung bình 4,0\nerror line 5: bad score ''''\ncsv HS-1029,Hoàng Thu Trang,8.9\nsms Hoàng Thu Trang - điểm trung bình 8,9\nexported 2, errors 4"', 3, false, true, 5),
