-- challenge chal_quiz_csf_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_csf_221', (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-csf-2-2' AND is_deleted = false LIMIT 1), 'linq-deferred-execution-quiz', 'Predict it: when does a LINQ query run?', 'Run a deferred query in your head after its inputs change, then decide which LINQ statements behave the way their authors expected.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_221'), 'What does this print?

var days = new List<int> { 2, 8, 6 };
int grace = 5;
var late = days.Where(d => d > grace);

grace = 7;
days.Add(10);

Console.WriteLine(string.Join(",", late));', 'single_choice'::question_type, 'Where does not run when the query is defined: late only stores the source list and the lambda. string.Join enumerates it at the last line, and at that moment the lambda reads the CURRENT value of the captured variable grace (7) and walks the CURRENT list (2, 8, 6, 10). 8 > 7 and 10 > 7, so it prints "8,10". "8,6" is what you would get by calling ToList() right after Where, when grace was still 5 and 10 was not in the list. "8,6,10" mixes the old grace with the new list, and "8" the new grace with the old list.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('8,6', false),
        ('8,6,10', false),
        ('8,10', true),
        ('8', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_221'), 'Which of these statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'scores.Where(s => s > 8).Count() and scores.Count(s => s > 8) count the same elements; the second is just shorter. ToList() enumerates the query at once and copies the results into a new list, which later changes to the source do not affect. Average() on an empty sequence of double throws InvalidOperationException "Sequence contains no elements" (Sum() returns 0, Average() has no value to return). FirstOrDefault() on an empty List<string> returns default(string), which is null. ids.Select(id => Send(id)) sends nothing at that line: Select is deferred, so Send runs only when something enumerates the query, and once more on every further enumeration. Single(predicate) throws InvalidOperationException "Sequence contains more than one matching element" when several elements match; it never picks one.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('scores.Where(s => s > 8).Count() and scores.Count(s => s > 8) return the same number', true),
        ('After var list = query.ToList(), adding items to the query''s source list does not change list', true),
        ('new List<double>().Average() returns 0', false),
        ('new List<string>().FirstOrDefault() returns null', true),
        ('var sent = ids.Select(id => Send(id)); sends every SMS exactly once, at this line', false),
        ('Single(predicate) returns the first match when several elements match', false)
    ) AS o(option_text, is_correct);

