-- challenge chal_quiz_csf_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_csf_311', (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-csf-3-1' AND is_deleted = false LIMIT 1), 'records-equality-quiz', 'Predict it: equality, with-expressions and hash codes', 'Follow a record with a list inside through a with-expression, then decide which statements about class and record equality are true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_311'), 'What does this program print?

var a = new Course("TOAN9-A", ["HS-1024"]);
var b = a with { };
b.Students.Add("HS-1025");
var c = new Course("TOAN9-A", ["HS-1024", "HS-1025"]);
Console.WriteLine($"{a == b} {a.Students.Count} {a == c}");

record Course(string Code, List<string> Students);', 'single_choice'::question_type, 'A with-expression makes a shallow copy: b is a new Course, but its Students property holds the same List<string> reference as a''s. b.Students.Add therefore adds to the one list both records share, so a.Students.Count is 2. Record equality compares each property with its default equality: Code is equal, and Students is the same reference, so a == b is True. c has its own list with the same two ids, but List<T> does not override Equals, so the lists are compared by reference and a == c is False. "False 1 False" would need with to copy the list (a deep copy); "True 2 True" would need records to compare list contents.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('False 1 False', false),
        ('True 2 False', true),
        ('True 2 True', false),
        ('False 2 True', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_311'), 'Which of these statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'HashSet first compares hash codes and only calls Equals for items in the same bucket. A class that overrides Equals but not GetHashCode keeps object''s reference-based hash code, so two equal objects usually land in different buckets and both stay in the set (the compiler warns with CS0659). For classes, == compares references unless the class declares operator ==; overriding Equals does not change it. The properties of a positional record are init-only, so e.StudentId = "x" after construction is error CS8852. A readonly record struct gets value-based Equals and GetHashCode, so it works as a Dictionary or HashSet key. Records compare strings with the default string equality, which is ordinal and case-sensitive: "hs-1024" and "HS-1024" are different, so normalize before you build the record. with copies the property values; a property that holds a list still points at the same list.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_311') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('A class that overrides Equals but not GetHashCode can end up twice in a HashSet even though the two objects are Equal', true),
        ('Once a class overrides Equals, a == b on two of its instances calls that Equals', false),
        ('With record Enrollment(string StudentId, string ClassCode, string Month), writing e.StudentId = "HS-1025" after construction does not compile', true),
        ('readonly record struct ClassTerm(string ClassCode, string Term) can be used as a Dictionary key: two keys with the same class code and term find the same entry', true),
        ('Records compare strings ignoring letter case, so new Enrollment("hs-1024", ...) equals new Enrollment("HS-1024", ...)', false),
        ('a with { Month = "2026-11" } makes a deep copy: lists inside a are copied too', false)
    ) AS o(option_text, is_correct);

