-- challenge chal_quiz_csf_411 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_csf_411', (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-csf-4-1' AND is_deleted = false LIMIT 1), 'exceptions-tryparse-quiz', 'Predict it: catch, finally and rethrowing', 'Follow an exception through try, catch and finally, then decide which statements about catching, rethrowing, TryParse and guard clauses are true.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_411'), 'What does this print?

try
{
    Console.Write("a ");
    int.Parse("vắng");
    Console.Write("b ");
}
catch (FormatException)
{
    Console.Write("c ");
}
catch (Exception)
{
    Console.Write("d ");
}
finally
{
    Console.Write("e ");
}
Console.Write("f");', 'single_choice'::question_type, 'int.Parse("vắng") throws a FormatException, so the rest of the try block is skipped: "b " is never printed. The runtime picks the FIRST catch clause whose type matches, which is catch (FormatException): it prints "c ". Only one catch clause runs, so catch (Exception) does not run even though a FormatException is also an Exception. finally runs on every way out of the try statement and prints "e ". The exception was handled, so execution continues after the try statement and prints "f". The output is "a c e f".', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_411') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('a b e f', false),
        ('a c e f', true),
        ('a c d e f', false),
        ('a c e', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_411'), 'Which of these statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'throw; inside a catch block rethrows the exception being handled and keeps its stack trace, so the trace still shows the method that failed; throw ex; throws the same object again but restarts the stack trace at that line. A catch (Exception) before a catch (FormatException) is the compile error CS0160 ("A previous catch clause already catches all exceptions of this or of a super type"), because the second clause could never run. int.TryParse("12a", out var n) returns false and sets n to 0, the default of int. ArgumentOutOfRangeException.ThrowIfGreaterThan(score, 10m) throws only when score is greater than 10, so exactly 10 is accepted. finally also runs when the try block leaves with return, break or an exception. An exception filter (catch ... when (condition)) only catches exceptions for which the condition is true; the others keep propagating as if the clause were not there.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_csf_411') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Inside a catch block, throw; keeps the original stack trace, while throw ex; restarts it at the throw ex; line', true),
        ('catch (Exception) { } placed before catch (FormatException) { } compiles, and the second clause handles format errors', false),
        ('int.TryParse("12a", out var n) returns false and sets n to 0', true),
        ('ArgumentOutOfRangeException.ThrowIfGreaterThan(score, 10m) throws when score is exactly 10', false),
        ('A finally block does not run when the try block leaves with return', false),
        ('catch (IOException ex) when (ex.Message.Contains("locked")) only catches the IOExceptions whose message contains "locked"; the others keep propagating', true)
    ) AS o(option_text, is_correct);

