-- challenge chal_coding_csf_421 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_csf_421', (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'csharp-foundations') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-csf-4-2' AND is_deleted = false LIMIT 1), 'term-class-report', 'Build the end-of-term class report', 'Sen Academy''s teachers and parents get one report per class at the end of the term. Extend the lesson''s TermReport into BuildReport: reject bad lines with their line number and reason, let a later line correct an earlier one, compute each student''s weighted average with decimal and round a half up, rank it on the Vietnamese scale, and print one block per class with the class average, the students in a stable order, the incomplete students with their missing components and the number of students per rank, then the rejected lines. The test runner switches to the Long Biên server''s culture (vi-VN) before it calls BuildReport, so parsing and formatting must not depend on the current culture.', 'open', 'hard'::difficulty_question, 'mini_coding', 30, true, false)
